examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    // The title and description sit above the card, as on the web; the rows are divided and the footer is a bar.
    VStack(alignment: .leading, spacing: theme.spacing.space1) {
        Text({{title}}).monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault)
            .accessibilityAddTraits(.isHeader)
        Text({{description}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
    }
    VStack(spacing: 0) {
        MonarchTextField({{rows.0.label}}, text: $displayName, helper: {{rows.0.description}}, isRequired: {{rows.0.required}})
            .padding(theme.spacing.space4)
        Rectangle().fill(theme.colors.borderSubtle).frame(height: 1)
        Toggle({{rows.1.label}}, isOn: $showsStatus)
            .monarchTextStyle(.label)
            .padding(theme.spacing.space4)
        Rectangle().fill(theme.colors.borderSubtle).frame(height: 1)
        MonarchButton({{action}}, variant: .primary) {}
            .frame(maxWidth: .infinity, alignment: .trailing)
            .padding(theme.spacing.space3)
            .background(theme.colors.bgSubtle)
    }
    .background(theme.colors.bgSurface)
    .clipShape(RoundedRectangle(cornerRadius: theme.radius.lg))
    .overlay(RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(theme.colors.borderSubtle, lineWidth: 1))
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var displayName = {{rows.0.value}}
@State private var showsStatus = {{rows.1.on}}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var displayName = "Ada Lovelace"
@State private var showsStatus = true

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    // The title and description sit above the card, as on the web; the rows are divided and the footer is a bar.
    VStack(alignment: .leading, spacing: theme.spacing.space1) {
        Text("Profile").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault)
            .accessibilityAddTraits(.isHeader)
        Text("How you appear to your teammates.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
    }
    VStack(spacing: 0) {
        MonarchTextField("Display name", text: $displayName, helper: "Shown on comments and assignments.", isRequired: true)
            .padding(theme.spacing.space4)
        Rectangle().fill(theme.colors.borderSubtle).frame(height: 1)
        Toggle("Show my status", isOn: $showsStatus)
            .monarchTextStyle(.label)
            .padding(theme.spacing.space4)
        Rectangle().fill(theme.colors.borderSubtle).frame(height: 1)
        MonarchButton("Save", variant: .primary) {}
            .frame(maxWidth: .infinity, alignment: .trailing)
            .padding(theme.spacing.space3)
            .background(theme.colors.bgSubtle)
    }
    .background(theme.colors.bgSurface)
    .clipShape(RoundedRectangle(cornerRadius: theme.radius.lg))
    .overlay(RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(theme.colors.borderSubtle, lineWidth: 1))
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var digest = false
@State private var saved = true

examples.code:
MonarchSectionCard("Workspace", description: "Changes apply to everyone in the workspace.") {
    Toggle("Weekly digest", isOn: $digest)
        .monarchTextStyle(.body)
} actions: {
    EmptyView()
} footer: {
    if digest != saved {
        Text("You have unsaved changes.")
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        MonarchButton("Discard", variant: .ghost, size: .sm) { digest = saved }
        MonarchButton("Save changes", variant: .primary, size: .sm) { saved = digest }
    }
}
